                        // default, no validation (use current user)
                    }
                } else {
                    char *end = NULL;
                    errno = 0;
                    long v = strtol(arg, &end, 10);
                    int is_numeric = (end != arg && *end == '\0' && errno == 0 && v >= 0 && v <= 4294967294L);
                    if (is_numeric) {
                    } else {
                        struct passwd *pw = getpwnam(arg);
                        if (!pw) {
                            fprintf(stderr, "Error: invalid user \"%s\".\n", arg);
                            return 1;
                        }
                    }
                }
                break;
            }
            case 'U':
                break;
            case 'V': {
                fputs(version_text, stdout);
                return 0;
            }
            case 1000: // no-meters
                break;
            case 1001: // no-functionbar/bar
                break;
            case 1002: // readonly
                break;
            case '?':
            default:
                // getopt already printed error
                return 1;
        }
    }

    // check non-options
    if (optind < argc) {
        // join with space
        // compute length
        size_t total = 0;
        for (int i = optind; i < argc; i++) {
            total += strlen(argv[i]) + 1;
        }
        char *buf = malloc(total + 1);
