// UI includes
#include <ncurses.h>
#include <term.h>

// Process info
typedef struct {
    int pid;
    int ppid;
    int pgrp;
    int session;
    char tty[64];
    char state;
    long utime;
    long stime;
    long priority;
    long nice;
    unsigned long long starttime;
    int processor;
