    uid_t uid;
    double cpu_percent;
    double mem_percent;
    unsigned long long total_time;
    char command[1024];
    char comm[256];
    int nlwp;
} ProcInfo;

static int g_ncpu = 1;
static long g_clk_tck = 100;
static long g_page_size = 4096;
static unsigned long long g_mem_total = 0;

static void read_system_info() {
    g_clk_tck = sysconf(_SC_CLK_TCK);
    if (g_clk_tck <= 0) g_clk_tck = 100;
    g_page_size = sysconf(_SC_PAGESIZE);
    if (g_page_size <= 0) g_page_size = 4096;
    // cpu count
    FILE *f = fopen("/proc/stat", "r");
    if (f) {
        char line[1024];
        int cnt = 0;
        while (fgets(line, sizeof(line), f)) {
            if (strncmp(line, "cpu", 3)==0 && isdigit((unsigned char)line[3])) cnt++;
        }
        fclose(f);
        if (cnt>0) g_ncpu = cnt;
    }
    // mem total
    f = fopen("/proc/meminfo", "r");
    if (f) {
        char line[256];
        while (fgets(line, sizeof(line), f)) {
            if (sscanf(line, "MemTotal: %llu", &g_mem_total)==1) {
                // g_mem_total in kB
                break;
            }
        }
        fclose(f);
    }
}

static int read_proc_info(int pid, ProcInfo *p) {
    char path[64];
    char buf[4096];
    memset(p, 0, sizeof(*p));
    p->pid = pid;
    // stat
    snprintf(path, sizeof(path), "/proc/%d/stat", pid);
    FILE *f = fopen(path, "r");
    if (!f) return -1;
    // stat format: pid (comm) state ppid pgrp session tty_nr tpgid flags minflt cminflt majflt cmajflt utime stime cutime cstime priority nice num_threads itrealvalue starttime vsize rss ...
    // comm may contain spaces/parens, need to parse carefully
    if (!fgets(buf, sizeof(buf), f)) { fclose(f); return -1; }
    fclose(f);
    // find '(' and ')'
    char *l = strchr(buf, '(');
    char *r = strrchr(buf, ')');
    if (!l || !r || r<=l) return -1;
    size_t commlen = r - l - 1;
    if (commlen >= sizeof(p->comm)) commlen = sizeof(p->comm)-1;
    memcpy(p->comm, l+1, commlen);
    p->comm[commlen]='\0';
    // after ')'
    char *rest = r+1;
    // rest starts with " state ..."
    char state = 0;
    int ppid=0, pgrp=0, session=0, tty_nr=0, tpgid=0;
    unsigned long flags=0, minflt=0, cminflt=0, majflt=0, cmajflt=0;
    unsigned long utime=0, stime=0;
    long cutime=0, cstime=0, priority=0, nice=0, nlwp=0;
    unsigned long long starttime=0, vsize=0;
    long rss=0;
    int processor=0;
