    // Simplify: parse first 39 fields
    int n = sscanf(rest, " %c %d %d %d %d %d %lu %lu %lu %lu %lu %lu %ld %ld %ld %ld %ld %ld %llu %lu %ld",
        &state, &ppid, &pgrp, &session, &tty_nr, &tpgid,
        &flags, &minflt, &cminflt, &majflt, &cmajflt,
        &utime, &stime, &cutime, &cstime,
        &priority, &nice, &nlwp, &starttime, &vsize, &rss);
    if (n < 10) return -1;
    p->state = state;
    p->ppid = ppid;
    p->pgrp = pgrp;
    p->session = session;
    snprintf(p->tty, sizeof(p->tty), "%d", tty_nr);
    p->utime = utime;
    p->stime = stime;
