        if (header_row >= maxy) header_row = 0;
        // column header
        attron(A_BOLD);
        mvprintw(header_row, 0, "%7s %-8s %3s %3s %5s %5s %3s %5s %5s %8s %s",
            "PID", "USER", "PRI", "NI", "VIRT", "RES", "S", "CPU%", "MEM%", "TIME+", "Command");
        attroff(A_BOLD);
        // collect processes
        ProcInfo *procs = NULL;
        size_t nprocs = 0, cap = 0;
        DIR *d = opendir("/proc");
        if (d) {
            struct dirent *e;
            while ((e=readdir(d))) {
                if (!isdigit((unsigned char)e->d_name[0])) continue;
                int pid = atoi(e->d_name);
                ProcInfo p;
                if (read_proc_info(pid, &p)!=0) continue;
                if (!filter_proc(&p)) continue;
                if (nprocs >= cap) {
