            attroff(A_REVERSE);
        }
        refresh();
        iter++;
        if (!infinite && iter >= max_iter) break;
        if (infinite) {
            // wait for delay and check input
            // delay in tenths: g_delay *100ms
            int delay_ms = g_delay * 100;
            if (delay_ms<100) delay_ms=100;
            if (delay_ms>10000) delay_ms=10000;
            timeout(delay_ms);
            ch = getch();
            if (ch=='q' || ch=='Q' || ch==27) break;
